import math

def lcm(a,b):
    return a*b // math.gcd(a,b)

def verifier(assign):
    # Basic validation of fields
    try:
        a = int(assign['a']); b = int(assign['b'])
        p = int(assign['p']); q = int(assign['q']); t = int(assign['t'])
        c = int(assign['c']); r = int(assign['r'])
        allowed_i = list(assign['allowed_i'])
        allowed_j = list(assign['allowed_j'])
    except Exception:
        # Missing or malformed fields
        return (False, None)
    # Domain checks
    if not (a >= 2 and b >= 2):
        return (False, None)
    if not (p >= 2 and q >= 2 and t >= 2):
        return (False, None)
    if not (0 <= r < t):
        return (False, None)
    if not (1 <= c < t):
        return (False, None)
    # Ensure allowed sets are proper nonempty proper subsets, and sizes >= 2 for difficulty
    if any(not (0 <= x < p) for x in allowed_i):
        return (False, None)
    if any(not (0 <= y < q) for y in allowed_j):
        return (False, None)
    si = len(set(allowed_i)); sj = len(set(allowed_j))
    if not (2 <= si <= p-1):
        return (False, None)
    if not (2 <= sj <= q-1):
        return (False, None)
    # Build period and residue classes
    L = lcm(lcm(p, q), t)
    if L <= 1:
        return (False, None)
    i_res = [ri for ri in range(L) if (ri % p) in set(allowed_i)]
    j_res = [rj for rj in range(L) if (rj % q) in set(allowed_j)]
    if not i_res or not j_res:
        return (False, None)
    # Valid residue pairs satisfying the coupling congruence
    valid_pairs = []
    for ri in i_res:
        for rj in j_res:
            if (ri + c*rj - r) % t == 0:
                valid_pairs.append((ri, rj))
    if len(valid_pairs) == 0:
        # Zero-area trivial case not allowed for difficulty
        return (False, None)
    # Enforce nontrivial coupling: j-residues must span at least two distinct classes modulo t/gcd(c,t)
    g = math.gcd(c, t)
    base_mod = t // g
    rj_mods = set((rj % base_mod) for rj in j_res)
    if len(rj_mods) < 2:
        return (False, None)
    # Compute area exactly using periodic decomposition
    # Each (i,j) with i = ri + nL, j = rj + mL contributes a rectangle of area
    # ((a-1)/a) * ((b-1)/b) * a^{-(ri+nL)} * b^{-(rj+mL)}.
    # Summing over n,m >= 0 gives ((a-1)/a) * ((b-1)/b) * (a^{-ri} * b^{-rj}) * (1/(1 - a^{-L})) * (1/(1 - b^{-L})).
    aL = pow(a, L); bL = pow(b, L)
    Ka = Fraction(aL, aL - 1)
    Kb = Fraction(bL, bL - 1)
    front = Fraction(a - 1, a) * Fraction(b - 1, b)
    sum_res = Fraction(0, 1)
    for (ri, rj) in valid_pairs:
        sum_res += Fraction(1, pow(a, ri) * pow(b, rj))
    area = front * Ka * Kb * sum_res
    # Ensure area is within (0,1] as a sanity check
    if area <= 0:
        return (False, None)
    # Return m + n for reduced fraction area
    m_plus_n = area.numerator + area.denominator
    return True, int(m_plus_n)


        def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
            """Return dict with assignment/question/answer or raise RuntimeError."""
            start = time.time()
            attempts = 0
            while time.time() - start < timeout_seconds:
                attempts += 1
                rng = _RNGShim(seed + attempts)
                assignment = generator(rng)
                valid, answer = verifier(assignment)
                if valid:
                    question = LANGUAGE_WRAPPER.format(**assignment)
                    return {
                        "assignment": assignment,
                        "question": question,
                        "answer": answer,
                        "attempts": attempts,
                        "elapsed_seconds": time.time() - start,
                    }
            raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

